def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if np.any(valid):
        trimmed_mean = np.mean(np.sort(remaining[valid])[1:-1]) if np.sum(valid) > 2 else np.mean(remaining[valid])
    else:
        trimmed_mean = 0.0
    scores = np.where(valid, -1.0 / (1.0 + np.abs(remaining - trimmed_mean)), -np.inf)
    return scores
```

